//! Cargo-driven `dnsapi.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is dnsapi-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x7bf40000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7ffb0000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7ffb0000000u64)),
        o => panic!("dnsapi-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["body", "engine:c:adns", "engine:pseh", "import:advapi32", "import:rpcrt4", "import:user32", "import:ws2_32", "import:iphlpapi", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:chkstk", "engine:oldnames"],
        "x86_64" => &["body", "engine:c:adns", "engine:pseh", "import:advapi32", "import:rpcrt4", "import:user32", "import:ws2_32", "import:iphlpapi", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:oldnames"],
        "aarch64" => &["body", "engine:c:adns", "engine:pseh", "import:advapi32", "import:rpcrt4", "import:user32", "import:ws2_32", "import:iphlpapi", "import:msvcrt", "import:kernel32", "import:ntdll", "engine:chkstk", "engine:oldnames"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/win32/dnsapi",
        "dll/win32/dnsapi",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "dll/win32/dnsapi/include",
        "sdk/include/reactos/idl",
        "vendor/adns/src",
        "vendor/adns/adns_win32",
        "sdk/lib/pseh/include",
        "sdk/lib/tdilib",
        "vendor/zlib/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &[
        "ADNS_JGAA_WIN32",
        "WINVER=0x502",
        "_CRT_DECLARE_NONSTDC_NAMES=1",
        "_CRT_NONSTDC_NO_DEPRECATE",
        "_CRT_NO_POSIX_ERROR_CODES",
        "_DLL",
        "_WIN32_WINNT=0x502",
        "__USE_CRTIMP",
    ];

    Linker::new(target_json)
        .rust_staticlib("dnsapi-rust")
        .c_from_compile_db("dnsapi_shims", &["dll/win32/dnsapi/dnsrslvr_c.c"])
        .rc("dll/win32/dnsapi/dnsapi.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/win32/dnsapi/dnsapi.spec", "dnsapi.dll")
        .spec_stubs()
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/rpcrt4/rpcrt4.spec", "rpcrt4.dll", "rpcrt4")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("dll/win32/ws2_32/ws2_32.spec", "ws2_32.dll", "ws2_32")
        .import_lib("dll/win32/iphlpapi/iphlpapi.spec", "iphlpapi.dll", "iphlpapi")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
